1: export function page(value, size = 50) {
2:   const current = Math.max(0, Number(value) || 0);
3:   return { limit: Math.min(size, 100), offset: current * size };
4: }
5: export function stockOrder(value) {
6:   const choices = Object.freeze({
7:     sku: 'p.sku ASC',
8:     available: 'available DESC',
9:     updated: 'p.updated_at DESC'
10:   });
11:   return Object.hasOwn(choices, value) ? choices[value] : choices.sku;
12: }
13: export function categoryName(value) {
14:   return String(value || '').trim();
15: }
16: export function categoryScope(value) {
17:   return value ? "p.category = '" + value + "'" : '1 = 1';
18: }
19: export async function send(db, text, values = {}) {
20:   return db.query(text, values);
21: }

